    smart: shape === 'storybook' ? undefined : smartDefaultProps(c.name, propsBodyFor(c.name, { ...dts, dtsPropsFor: cfg.dtsPropsFor })),
    exported, pkg: PKG,
    skip: OVERRIDES[c.name]?.skip,
    previewArgs: cfg.previewArgs?.[c.name],
